import { decodeDomainSet, type EncodedDomainSet } from '../lib/domain-set';
import encoded from './popular-top100k.json';

/**
 * Bundled popular registrable domains: in the top 100k of the Majestic Million or of the Chrome
 * UX Report (generated by `npm run build:data`, ticket 19). Exact 32-bit hash set: no false
 * negatives, false-positive rate ≈ n / 2³² (≈ 4e-5 for ~160k domains).
 */
export const popularTop100k = decodeDomainSet(encoded as EncodedDomainSet);

/** True when the registrable domain is in the bundled popular top-100k set. */
export function has(domain: string): boolean {
  return popularTop100k.has(domain);
}
